try {
    // 1. Data Extraction
    const scenarioName = pm.iterationData.get("scenario");
    const isSuccess = pm.iterationData.get("is_success") === true || pm.iterationData.get("is_success") === "true";
    
    // 2. Initial Assertion
    pm.test(`[${scenarioName}] Status code is 200`, function () {
        pm.response.to.have.status(200);
    });
    
    // 3. Guard Clause: Abort if status code is unexpected
    if (pm.response.code !== 200) {
        console.warn(`[${scenarioName}] Unexpected status code. Aborting JSON parsing and assertions.`);
        return;
    }
    
    // 4. Parse Response
    const responseJson = pm.response.json();
    
    // 5. Dynamic Branching Assertions
    if (isSuccess) {
        pm.test(`[${scenarioName}] Token is successfully retrieved`, function () {
            pm.expect(responseJson.token).to.not.be.undefined;
            pm.collectionVariables.set("token", responseJson.token);
        });
    } else {
        const expectedMsg = pm.iterationData.get("expected_error_msg");
        pm.test(`[${scenarioName}] Error message matches expected value: ${expectedMsg}`, function () {
            pm.expect(responseJson.reason).to.eql(expectedMsg);
        });
    }

} finally {
    // Cleanup variables
    pm.variables.unset("dynamicBody");
}

try {
