    const responseJson = pm.response.json();
    
    // 5. Dynamic Branching Assertions: Verify and save Booking ID
    pm.test(`[${scenarioName}] Booking ID is generated`, function () {
        pm.expect(responseJson.bookingid).to.not.be.undefined;
        pm.expect(responseJson.bookingid).to.be.a("number");
    });
    
    // 6. Full Object Validation: Construct the expected object representing the desired backend state
    const expectedBooking = {
        firstname: pm.iterationData.get("firstname"),
        lastname: pm.iterationData.get("lastname"),
        totalprice: parseInt(pm.iterationData.get("totalprice"), 10),
        // Handle CSV string to boolean conversion
        depositpaid: pm.iterationData.get("depositpaid") === "true" || pm.iterationData.get("depositpaid") === true,
        bookingdates: {
            checkin: pm.iterationData.get("checkin"),
            checkout: pm.iterationData.get("checkout")
        },
        additionalneeds: pm.iterationData.get("additionalneeds")
    };
    
    // Validate the entire response object against the constructed expected object
    pm.test(`[${scenarioName}] Booking data perfectly matches input (Deep Equality)`, function () {
        pm.expect(responseJson.booking).to.eql(expectedBooking);
    });

} finally {
    // Cleanup variables
